-- New columns go last, so the views are replaced in place: reply_by_evidence reads enrollment_outcomes.
CREATE OR REPLACE VIEW "public"."enrollment_outcomes" AS (WITH opener AS ( SELECT m.enrollment_id, m.template AS opener_template, m.template_version AS opener_template_version, m.state AS opener_state, m.provenance -> 'address'::text AS address FROM messages m WHERE m.step = 0 ), sends AS ( SELECT m.enrollment_id, count(*) FILTER (WHERE m.state::text = 'sent'::text) AS steps_sent, min(m.sent_at) AS first_sent_at, max(m.sent_at) AS last_sent_at, max(m.sent_at) FILTER (WHERE m.state::text = 'sent'::text) AS last_delivered_at FROM messages m GROUP BY m.enrollment_id ), events AS ( SELECT te.enrollment_id, count(*) FILTER (WHERE te.kind::text = 'reply'::text) AS replies, bool_or(te.kind::text = 'reply'::text) AS replied, bool_or(te.kind::text = 'reply'::text AND (te.disposition::text = ANY (ARRAY['interested'::character varying, 'meeting_booked'::character varying]::text[]))) AS interested, bool_or(te.kind::text = 'bounce'::text AND te.bounce_class::text = 'hard'::text) AS hard_bounced, bool_or(te.kind::text = 'bounce'::text AND te.bounce_class::text = 'soft'::text) AS soft_bounced, bool_or(te.kind::text = 'unsubscribe'::text) AS unsubscribed, bool_or(te.kind::text = 'complaint'::text) AS complained, bool_or(te.kind::text = 'auto_reply'::text) AS auto_replied, min(te.received_at) FILTER (WHERE te.kind::text = 'reply'::text) AS first_reply_at, (array_agg(te.disposition ORDER BY te.received_at DESC, te.id DESC) FILTER (WHERE te.kind::text = 'reply'::text AND te.disposition IS NOT NULL))[1] AS disposition, max(te.received_at) AS last_event_at, bool_or(te.kind::text = ANY (ARRAY['unsubscribe'::text, 'complaint'::text])) AS opted_out, COALESCE((array_agg(COALESCE(te.disposition::text, 'other'::text) ORDER BY te.received_at DESC, te.id DESC) FILTER (WHERE te.kind::text = 'reply'::text))[1] = 'other'::text, false) AS needs_a_look FROM thread_events te GROUP BY te.enrollment_id ) SELECT e.id AS enrollment_id, e.niche, e.sequence_name, e.kind AS enrollment_kind, e.company_id, e.person_id, e.to_email, e.sender, e.state, e.stop_reason, e.created_at AS enrolled_at, o.opener_template, o.opener_template_version, o.opener_state, o.address ->> 'evidence'::text AS evidence, o.address ->> 'verification_result'::text AS verification_result, o.address ->> 'pick_method'::text AS pick_method, e.lead_id, e.candidate_id, (o.address ->> 'document_id'::text)::integer AS source_document_id, o.address ->> 'source_url'::text AS source_url, COALESCE(s.steps_sent, 0::bigint) AS steps_sent, s.first_sent_at, s.last_sent_at, COALESCE(ev.replies, 0::bigint) AS replies, COALESCE(ev.replied, false) AS replied, COALESCE(ev.interested, false) AS interested, ev.disposition, COALESCE(ev.hard_bounced, false) AS hard_bounced, COALESCE(ev.soft_bounced, false) AS soft_bounced, COALESCE(ev.unsubscribed, false) AS unsubscribed, COALESCE(ev.complained, false) AS complained, COALESCE(ev.auto_replied, false) AS auto_replied, ev.first_reply_at, e.contact_round, e.offer, GREATEST(e.created_at, e.stopped_at, s.last_delivered_at, ev.last_event_at) AS last_touch_at, CASE WHEN e.state::text = 'active'::text THEN 'active'::text WHEN (e.stop_reason::text = ANY (ARRAY['opt_out'::text, 'complaint'::text])) OR ev.opted_out THEN 'opted_out'::text WHEN ev.interested OR e.stop_reason::text = 'booked'::text OR (EXISTS ( SELECT 1 FROM call_bookings cb WHERE cb.enrollment_id = e.id)) THEN 'warm'::text WHEN e.stop_reason::text = 'manual'::text THEN 'stopped_by_hand'::text WHEN ev.needs_a_look THEN 'needs_a_look'::text WHEN ev.disposition::text = ANY (ARRAY['not_interested'::text, 'not_now'::text, 'wrong_person'::text, 'referral'::text]) THEN ev.disposition::text WHEN e.stop_reason::text = 'bounce'::text OR ev.hard_bounced THEN 'bounced'::text ELSE 'no_reply'::text END AS outcome FROM enrollments e LEFT JOIN opener o ON o.enrollment_id = e.id LEFT JOIN sends s ON s.enrollment_id = e.id LEFT JOIN events ev ON ev.enrollment_id = e.id);--> statement-breakpoint
CREATE OR REPLACE VIEW "public"."contact_outcomes" AS (SELECT enrollment_id, company_id, niche, sequence_name, offer, to_email, contact_round, enrolled_at, last_touch_at, outcome FROM enrollment_outcomes);
